#ifndef SCAMPTRIE_DYNAMIC_H
#define SCAMPTRIE_DYNAMIC_H

#include "scamptrie_base.h"
#include <vector>
#include <unordered_map>
#include <cstddef>

// The CPU model keeps the authoritative FIB explicitly.  The packed trie is
// an immutable representation made by MemInit; keeping these two things
// separate is intentional (and also makes snapshots genuinely detached).
struct LivePrefix {
    ip6_t ip;
    uint8_t len;
    nexthop_t hop;
};

struct PrefixKey {
    uint64_t hi, lo;
    uint8_t len;
    bool operator==(const PrefixKey& o) const {
        return hi == o.hi && lo == o.lo && len == o.len;
    }
};
struct PrefixKeyHash {
    size_t operator()(const PrefixKey& k) const {
        uint64_t x = k.hi ^ (k.lo + 0x9e3779b97f4a7c15ULL +
                              (k.hi << 6) + (k.hi >> 2));
        x ^= static_cast<uint64_t>(k.len) * 0x517cc1b727220a95ULL;
        x ^= x >> 30; x *= 0xbf58476d1ce4e5b9ULL;
        x ^= x >> 27; x *= 0x94d049bb133111ebULL;
        return static_cast<size_t>(x ^ (x >> 31));
    }
};

class ScampTrieDynamic {
public:
    ScampTrieDynamic() = default;
    ~ScampTrieDynamic() = default;

    nexthop_t lookup(ip6_t ip, uint32_t &bmp_idx, int = 129) const;
    uint32_t insert_prefix(ip6_t prefix128, uint8_t len128, nexthop_t nh);

    void set_insert_prefix_timing_enabled(bool enabled) { insert_timing_enabled_ = enabled; }
    bool insert_prefix_timing_enabled() const { return insert_timing_enabled_; }

    std::vector<LivePrefix> prefixes() const;

private:
    std::unordered_map<PrefixKey, nexthop_t, PrefixKeyHash> fib_;
    bool insert_timing_enabled_ = true;
};

#endif
#include "mem_init.h"
#include "../scamptrie_dynamic.h"
#include "../prefix_table.hpp"
#include <algorithm>
#include <map>
#include <memory>
#include <set>
#include <stdexcept>

namespace {
static const uint32_t NULL_HOP = 4194303u;


struct BNode {
    unsigned origin;
    unsigned depth;
    ip6_t region;
    std::vector<LivePrefix> ps, local;
    std::vector<BNode*> children;
    std::vector<unsigned> keys;
    unsigned type=0;
    int stage=0;
    bool bulk=false;
    uint32_t cell=0;
    uint32_t bmp=NULL_HOP;
    uint64_t pattern=0;
    uint32_t bitmap_id=0, ni_base=0;
};

class ImageBuilder {
public:
    explicit ImageBuilder(const std::vector<LivePrefix>& p): allp(p) {}
    ImageData run() {
        ImageData d; d.root=ImageLoc();
        std::map<uint16_t,std::vector<LivePrefix>> p16;
        std::map<uint64_t,std::vector<LivePrefix>> p64;
        std::vector<LivePrefix> p0;
        for (auto p:allp) {
            if (p.len<=16) p0.push_back(p);
            else if (p.len<=64) p16[uint16_t(p.ip.hi>>48)].push_back(p);
            else p64[p.ip.hi].push_back(p);
        }
        if (!p0.empty()) roots0=make(p0,0,0,{0,0},16);
        for (auto& x:p16) roots16.push_back({x.first,make(x.second,16,16,{uint64_t(x.first)<<48,0},64)});
        for (auto& x:p64) roots64.push_back({x.first,make(x.second,64,64,{x.first,0},128)});
        if (roots0) allroots.push_back(roots0);
        for(auto x:roots16)allroots.push_back(x.second);
        for(auto x:roots64)allroots.push_back(x.second);
        for(auto n:allroots) set_stage(n);
        scamp::PrefixTable fib;
        for(auto p:allp) fib.insert(p.ip,p.len,uint32_t(p.hop));
        for(auto n:nodes) n->bmp=fib.lookup(n->region,n->depth);
        for(auto n:nodes) if(n->type<=3) patterns.insert(n->pattern);
        std::vector<uint64_t> pats(patterns.begin(),patterns.end());
        std::sort(pats.begin(),pats.end());
        d.bitmaps=pats;
        for(auto n:nodes) if(n->type<=3) {
            n->bitmap_id=uint32_t(std::lower_bound(pats.begin(),pats.end(),n->pattern)-pats.begin());
            std::vector<std::pair<unsigned,LivePrefix>> v;
            for(auto p:n->local) { unsigned l=p.len-n->depth; v.push_back({(1u<<l)|scamp::extract(p.ip,n->depth,l),p}); }
            std::sort(v.begin(),v.end(),[](const auto&a,const auto&b){return a.first<b.first;});
            n->ni_base=v.empty()?0:d.nexthops.size();
            for(auto x:v)d.nexthops.push_back(uint32_t(x.second.hop));
        }
        allocate(d);
        for(int s=0;s<RAM_NUM;++s) d.banks[s].assign((d.cells[s]+1)/2,std::bitset<256>());
        for(auto n:nodes) pack(d,n);
        if(roots0) d.root={roots0->stage,roots0->cell};
        for(auto x:roots16)d.front16.push_back({x.first,{x.second->stage,x.second->cell}});
        for(auto x:roots64)d.front64.push_back({x.first,{x.second->stage,x.second->cell}});
        return d;
    }
private:
    const std::vector<LivePrefix>& allp;
    std::vector<std::unique_ptr<BNode>> store;
    std::vector<BNode*> nodes,allroots;
    BNode* roots0=nullptr;
    std::vector<std::pair<uint16_t,BNode*>> roots16;
    std::vector<std::pair<uint64_t,BNode*>> roots64;
    std::set<uint64_t> patterns;

    BNode* make(const std::vector<LivePrefix>& ps,unsigned origin,unsigned depth,ip6_t region,unsigned maxlen) {
        std::unique_ptr<BNode> q(new BNode()); BNode* n=q.get(); store.push_back(std::move(q)); nodes.push_back(n);
        n->origin=origin;n->depth=depth;n->region=scamp::normalize(region,depth);
        if(ps.size()<=2) { n->type=unsigned(ps.size()==1?TYPE4:TYPE5); n->ps=ps; return n; }
        std::map<unsigned,std::vector<LivePrefix>> groups;
        for(auto p:ps) {
            if(p.len<=depth+5) n->local.push_back(p);
            else groups[scamp::extract(p.ip,depth,6)].push_back(p);
        }
        for(auto& g:groups) {
            if(depth+6>maxlen) throw std::logic_error("prefix beyond owner");
            ip6_t r=scamp::normalize(g.second[0].ip,depth+6);
            n->keys.push_back(g.first); n->children.push_back(make(g.second,origin,depth+6,r,maxlen));
        }
        unsigned c=n->children.size(); n->type=c<=2?TYPE1:(c<=6?TYPE2:TYPE3);
        n->pattern=0;
        for(auto p:n->local) { unsigned l=p.len-depth; n->pattern|=1ULL<<((1u<<l)|scamp::extract(p.ip,depth,l)); }
        return n;
    }
    int set_stage(BNode* n) {
        if(n->children.empty()) {n->stage=0;return 0;}
        int hi=0;
        for(auto c:n->children)hi=std::max(hi,set_stage(c));
        if(n->type==TYPE3) {
            // All TYPE3 children are bulk children.  A common stage is the
            // maximum required child stage.
            for(auto c:n->children){c->stage=hi;c->bulk=true;}
            n->stage=hi+1;
        } else {
            n->stage=hi+1;
        }
        return n->stage;
    }
    void put_field(std::bitset<256>& w,unsigned off,unsigned n,uint64_t v) {
        for(unsigned i=0;i<n;++i) w[off+i]=(v>>i)&1;
    }
    uint32_t child_raw(BNode* c,unsigned key) {
        return (uint32_t(key)&63u) | (uint32_t(c->stage)<<6) | (c->cell<<10);
    }
    void allocate(ImageData& d) {
        for(int s=0;s<RAM_NUM;++s) {
            uint32_t next=0;
            // Bulk arrays are allocated as complete contiguous two-cell slots.
            for(auto p:nodes) if(p->type==TYPE3) {
                if(p->children[0]->stage!=s) continue;
                for(auto c:p->children){c->cell=next;next+=2;}
            }
            for(auto n:nodes) if(n->stage==s && !n->bulk && n->type!=TYPE1 && n->type!=TYPE4) { n->cell=next;next+=2; }
            for(auto n:nodes) if(n->stage==s && !n->bulk && (n->type==TYPE1||n->type==TYPE4)) { n->cell=next++; }
            d.cells[s]=next;
        }
    }
    void pack(ImageData& d,BNode* n) {
        if(n->stage<0||n->stage>=RAM_NUM) throw std::runtime_error("stage");
        unsigned off=(n->type==TYPE2||n->type==TYPE3||n->type==TYPE5)?0:(n->cell&1)*128;
        std::bitset<256>& w=d.banks[n->stage][n->cell/2];
        put_field(w,off,3,n->type); put_field(w,off+3,22,n->bmp);
        if(n->type<=3) {
            put_field(w,off+25,16,n->bitmap_id);put_field(w,off+41,22,n->ni_base);
            if(n->type==TYPE1||n->type==TYPE2) {
                unsigned lim=n->type==TYPE1?2:6;
                for(unsigned i=0;i<lim;++i) put_field(w,off+63+32*i,32,i<n->children.size()?child_raw(n->children[i],n->keys[i]):(15u<<6));
                // one reserved bit is already zero
            } else {
                uint64_t bm=0; for(auto k:n->keys)bm|=1ULL<<k;
                put_field(w,off+63,64,bm);
                uint32_t base=n->children.empty()?0:n->children[0]->cell;
                put_field(w,off+127,22,base);put_field(w,off+149,4,n->children.empty()?0:n->children[0]->stage);
                for(unsigned i=0;i<3;++i) put_field(w,off+153+32*i,32,15u<<6);
            }
        } else {
            auto inline_one=[&](unsigned at,const LivePrefix& p){
                unsigned rel=p.len-n->origin; uint64_t f=0;
                for(unsigned i=0;i<rel;++i) if(scamp::extract(p.ip,n->origin+i,1)) f|=1ULL<<(63-i);
                put_field(w,off+at,64,f);put_field(w,off+at+64,8,rel);put_field(w,off+at+72,22,p.hop);
            };
            inline_one(25,n->ps[0]); if(n->type==TYPE5) inline_one(119,n->ps[1]);
        }
    }
};
}

ImageData MemInit::capture() {
    if(!trie) throw std::runtime_error("no trie");
    return ImageBuilder(trie->prefixes()).run();
}
